using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;

using RestaurantMenu.Restaurants.Domain.Memberships;
using RestaurantMenu.Restaurants.Domain.Restaurants;
namespace RestaurantMenu.Restaurants.Infrastructure.Database.Configurations;

internal sealed class MembershipInvitationConfiguration : IEntityTypeConfiguration<MembershipInvitation>
{ public void Configure(EntityTypeBuilder<MembershipInvitation> b) { b.ToTable("membership_invitations"); b.HasKey(x => x.Id); b.Property(x => x.Id).HasConversion(x => x.Value, x => new(x)).HasColumnName("id").ValueGeneratedNever(); b.Property(x => x.RestaurantId).HasConversion(x => x.Value, x => new(x)).HasColumnName("restaurant_id"); b.Property(x => x.Email).HasColumnName("email").HasMaxLength(320); b.Property(x => x.TokenHash).HasColumnName("token_hash").HasMaxLength(64); b.Property(x => x.Role).HasConversion<string>().HasColumnName("role").HasMaxLength(32); b.Property(x => x.Status).HasConversion<string>().HasColumnName("status").HasMaxLength(24); b.Property(x => x.InvitedBySubject).HasColumnName("invited_by_subject").HasMaxLength(255); b.Property(x => x.AcceptedBySubject).HasColumnName("accepted_by_subject").HasMaxLength(255); b.Property(x => x.CreatedAtUtc).HasColumnName("created_at_utc").HasColumnType("timestamp with time zone"); b.Property(x => x.ExpiresAtUtc).HasColumnName("expires_at_utc").HasColumnType("timestamp with time zone"); b.Property(x => x.AcceptedAtUtc).HasColumnName("accepted_at_utc").HasColumnType("timestamp with time zone"); b.Property(x => x.RevokedAtUtc).HasColumnName("revoked_at_utc").HasColumnType("timestamp with time zone"); b.Property(x => x.Version).HasColumnName("version").IsConcurrencyToken(); b.HasIndex(x => x.TokenHash).IsUnique().HasDatabaseName("ux_membership_invitations_token_hash"); b.HasIndex(x => new { x.RestaurantId, x.Email }).IsUnique().HasFilter("status = 'Pending'").HasDatabaseName("ux_membership_invitations_active_email"); b.HasOne<Restaurant>().WithMany().HasForeignKey(x => x.RestaurantId).OnDelete(DeleteBehavior.Restrict); } }